<script setup lang="ts">import events from '../../data/events.json';import {computed,ref} from 'vue';const f=ref('all');const list=computed(()=>events.events.filter((e:any)=>f.value==='all'||e.status===f.value).sort((a:any,b:any)=>(a.as??999)-(b.as??999)))</script><template><label>Filter <select v-model="f"><option>all</option><option>canonical</option><option>reported</option></select></label><div v-for="e in list" :key="e.id" class="lore-card" :class="`status-${e.status}`"><strong>{{e.name}}</strong> <span class="lore-status">{{e.status}}</span><p>{{e.ce}} · {{e.as===0?'Day 0':e.as+' AS'}}</p></div></template>
